private static final String LOG_TAG = AppLockUtil.class.getSimpleName();
private static final String APP_LOCK_DATA_VERSION_PREFIX = "app-lock-v";
private static final String CURRENT_APP_LOCK_DATA_PREFIX = APP_LOCK_DATA_VERSION_PREFIX + "2:";
private static final int LEGACY_APP_LOCK_PBKDF2_ITERATIONS = 1000;
private static final int APP_LOCK_PBKDF2_KEY_BYTES = 32;
public static final String FAILED_UNLOCK_ELAPSED_REALTIME = "failedUnlockElapsedRealtime";
