/**
 * Creates a credential value in the current, explicitly versioned app-lock format.
 */
public static String appLockDataHash(String data) {
    return CURRENT_APP_LOCK_DATA_PREFIX + UtilFunctions.appLockDataHash(data);
}

/**
 * Verifies a persisted app-lock credential and returns its current-format replacement on
 * success. A null result indicates that the supplied data does not verify. Callers may
 * persist a non-null result unconditionally: it equals the current value for an already
 * current credential and upgrades a successfully verified legacy credential.
 */
public static String verifyAndMigrateAppLockDataHash(String data, String persistedDataHash) {
    if (data == null || persistedDataHash == null) {
        return null;
    }

    String currentDataHash = appLockDataHash(data);
    if (persistedDataHash.startsWith(APP_LOCK_DATA_VERSION_PREFIX)) {
        return persistedDataHash.equals(currentDataHash) ? currentDataHash : null;
    }

    return persistedDataHash.equals(legacyAppLockDataHash(data)) ? currentDataHash : null;
}

private static String legacyAppLockDataHash(String data) {
    PBEKeySpec keySpec = new PBEKeySpec(
            data.toCharArray(),
            UtilFunctions.getAppSalt().getBytes(),
            LEGACY_APP_LOCK_PBKDF2_ITERATIONS,
            APP_LOCK_PBKDF2_KEY_BYTES * 8);
    try {
        SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
        byte[] encodedKey = keyFactory.generateSecret(keySpec).getEncoded();
        return Base64.encodeToString(encodedKey, Base64.DEFAULT);
    } catch (Exception e) {
        throw new IllegalStateException("Unable to verify legacy app-lock credential", e);
    } finally {
        keySpec.clearPassword();
    }
}

public interface OnSecurityCheckPerformedListener {
    void onAccessGranted();
}

