            new byte[]{0x01, 0x11, 0x21, 0x31, 0x41, 0x51, 0x61, 0x71, 0x02, 0x12, 0x22, 0x32},
            new byte[]{0x03, 0x13, 0x23, 0x33, 0x43, 0x53, 0x63, 0x73, 0x04, 0x14, 0x24, 0x34},
            new byte[]{0x05, 0x15, 0x25, 0x35, 0x45, 0x55, 0x65, 0x75, 0x06, 0x16, 0x26, 0x36}
    };

    @Test
    public void decryptCredentialDecryptsAccessTokenArgumentsInOrder() throws Exception {
        SecretKey key = testKey();
        String[] expectedAccessTokenArguments = new String[]{
                "fixture-access-token-argument-one",
                "fixture-access-token-argument-two",
                "fixture-access-token-argument-three"
        };
        MarketPriceFetcher.CredentialEnvelope[] envelopes = new MarketPriceFetcher.CredentialEnvelope[]{
                encryptedEnvelope(expectedAccessTokenArguments[0], key, TEST_IV_FIXTURES[0]),
                encryptedEnvelope(expectedAccessTokenArguments[1], key, TEST_IV_FIXTURES[1]),
                encryptedEnvelope(expectedAccessTokenArguments[2], key, TEST_IV_FIXTURES[2])
        };

        assertEquals(expectedAccessTokenArguments[0], MarketPriceFetcher.decryptCredential(envelopes[0], key));
        assertEquals(expectedAccessTokenArguments[1], MarketPriceFetcher.decryptCredential(envelopes[1], key));
        assertEquals(expectedAccessTokenArguments[2], MarketPriceFetcher.decryptCredential(envelopes[2], key));
    }

    @Test
    public void decryptCredentialRejectsTamperedCiphertextWithBadPaddingException() throws Exception {
        SecretKey key = testKey();
        MarketPriceFetcher.CredentialEnvelope envelope = encryptedEnvelope(
                "fixture-tamper-check", key, TEST_IV_FIXTURES[0]);
        byte[] tamperedCiphertext = Base64.decode(envelope.encodedCiphertext, Base64.NO_WRAP);
        tamperedCiphertext[tamperedCiphertext.length - 1] ^= 0x01;
        MarketPriceFetcher.CredentialEnvelope tamperedEnvelope = new MarketPriceFetcher.CredentialEnvelope(
                envelope.encodedIv,
                Base64.encodeToString(tamperedCiphertext, Base64.NO_WRAP));

        try {
            MarketPriceFetcher.decryptCredential(tamperedEnvelope, key);
            fail("Tampered AES/GCM ciphertext must fail authentication");
        } catch (BadPaddingException expected) {
            // AES/GCM authentication failures propagate through the contract's BadPaddingException boundary.
        }
    }

    private static SecretKey testKey() {
        return new SecretKeySpec(TEST_KEY_BYTES, "AES");
    }

    private static MarketPriceFetcher.CredentialEnvelope encryptedEnvelope(
            String plaintext, SecretKey key, byte[] iv) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(128, iv));
        byte[] ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
        return new MarketPriceFetcher.CredentialEnvelope(
                Base64.encodeToString(iv, Base64.NO_WRAP),
                Base64.encodeToString(ciphertext, Base64.NO_WRAP));
    }
}

